/*
 * A164776  Numbers k with property that average digit of k^2 is s=4.
 * https://oeis.org/A164776
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 7, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   digit_frequencies
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Numbers k whose average decimal digit of k² equals 4 */
/* The elements a(n) (n ≥ 1) are generated by brute‑force searching
   successive k and storing the ones that satisfy the condition. */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Helpers provided by the framework (digit_frequencies) */
#include "../utils/digit_frequencies.h"

static seq_t *cache      = NULL;   /* array of found terms */
static size_t cache_cap  = 0;       /* allocated capacity of cache   */
static size_t cache_len  = 0;       /* number of terms actually stored */
static uint64_t next_candidate = 1; /* next integer to test for k */

/* Ensure cache has room for at least 'needed' elements. */
static void ensure_cache_cap(size_t needed)
{
    if (needed <= cache_cap) return;

    size_t new_cap = cache_cap ? cache_cap * 2 : 8;
    while (new_cap < needed) new_cap <<= 1;

    seq_t *new_cache = (seq_t*)malloc(new_cap * sizeof(seq_t));
    if (!new_cache) exit(EXIT_FAILURE);        /* fatal if allocation fails */

    for (size_t i = 0; i < cache_len; ++i) new_cache[i] = cache[i];
    if (cache) free(cache);
    cache      = new_cache;
    cache_cap  = new_cap;
}

/* Return the n-th term of the sequence (n ≥ 1).  For n==0 we return 0. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;               /* undefined for n==0 */

    /* make sure we have at least n terms stored */
    ensure_cache_cap((size_t)n);

    while (cache_len < (size_t)n) {
        uint64_t k = next_candidate++;
        seq_t sq   = (seq_t)k * (seq_t)k;   /* compute k² in seq_t */

        unsigned int freq[10];
        digit_frequencies(sq, freq);

        /* compute digit count and digit sum */
        unsigned int dcnt = 0, dsum = 0;
        for (int d = 0; d < 10; ++d) {
            dcnt += freq[d];
            dsum += (unsigned int)d * freq[d];
        }

        /* average = 4 if and only if sum == 4 * count */
        if (dsum == 4 * dcnt) {
            /* store the term (as seq_t).  The cast may truncate if
               k exceeds the range of seq_t; that is acceptable because
               those terms will not fit in the target type anyway. */
            cache[cache_len++] = (seq_t)k;
        }
    }

    return cache[cache_len - 1];
}
